import sys
from typing import List

def max_cookies(n: int, k: int, a: List[int], b: List[int]) -> int:
    def can_bake(m: int) -> bool:
        return all((a[i] * m + b[i]) <= a[i] for i in range(n))

    left, right = 0, min(k // a[0], k // b[0])
    while left < right:
        mid = (left + right + 1) // 2
        if can_bake(mid):
            left = mid
        else:
            right = mid - 1
    return left

